SELECT DISTINCT p.product_id, p.name, p.category, p.price, p.stock_qty 
FROM products p 
WHERE NOT EXISTS (
    SELECT 1 FROM orders o 
    WHERE o.customer_id = p.customer_id AND o.order_date IS NULL
);

SELECT AVG(price) 
FROM products 
WHERE category = 'Electronics';

SELECT city, COUNT(*) AS num_customers
FROM customers
GROUP BY city;

SELECT *
FROM orders
WHERE YEAR(orders.joined_date) = 2024;

SELECT * FROM products 
ORDER BY price DESC 
LIMIT 5;
